          { name = "after", type = "String", description = "Returns the elements in the list that come after the specified cursor.", default_value = nil },
          { name = "before", type = "String", description = "Returns the elements in the list that come before the specified cursor.", default_value = nil },
          { name = "first", type = "Int", description = "Returns the first _n_ elements from the list.", default_value = nil },
          { name = "includeAsSponsor", type = "Boolean", description = "Whether to include those events where this sponsorable acted as the sponsor.\nDefaults to only including events where this sponsorable was the recipient\nof a sponsorship.", default_value = "false" },
          { name = "includePrivate", type = "Boolean", description = "Whether or not to include private activities in the result set. Defaults to including public and private activities.", default_value = "true" },
          { name = "last", type = "Int", description = "Returns the last _n_ elements from the list.", default_value = nil },
          { name = "orderBy", type = "SponsorsActivityOrder", description = "Ordering options for activity returned from the connection.", default_value = "{field: TIMESTAMP, direction: DESC}" },
          { name = "period", type = "SponsorsActivityPeriod", description = "Filter activities returned to only those that occurred in the most recent\nspecified time period. Set to ALL to avoid filtering by when the activity\noccurred. Will be ignored if `since` or `until` is given.", default_value = "MONTH" },
          { name = "since", type = "DateTime", description = "Filter activities to those that occurred on or after this time.", default_value = nil },
          { name = "until", type = "DateTime", description = "Filter activities to those that occurred before this time.", default_value = nil },
        } },
        { name = "sponsorsListing", type = "SponsorsListing", description = "The GitHub Sponsors listing for this user or organization.", args = {} },
        { name = "sponsorshipForViewerAsSponsor", type = "Sponsorship", description = "The sponsorship from the viewer to this user/organization; that is, the sponsorship where you're the sponsor.", args = {
          { name = "activeOnly", type = "Boolean", description = "Whether to return the sponsorship only if it's still active. Pass false to\nget the viewer's sponsorship back even if it has been cancelled.", default_value = "true" },
        } },
        { name = "sponsorshipForViewerAsSponsorable", type = "Sponsorship", description = "The sponsorship from this user/organization to the viewer; that is, the sponsorship you're receiving.", args = {
          { name = "activeOnly", type = "Boolean", description = "Whether to return the sponsorship only if it's still active. Pass false to\nget the sponsorship back even if it has been cancelled.", default_value = "true" },
        } },
        { name = "sponsorshipNewsletters", type = "SponsorshipNewsletterConnection!", description = "List of sponsorship updates sent from this sponsorable to sponsors.", args = {
          { name = "after", type = "String", description = "Returns the elements in the list that come after the specified cursor.", default_value = nil },
          { name = "before", type = "String", description = "Returns the elements in the list that come before the specified cursor.", default_value = nil },
          { name = "first", type = "Int", description = "Returns the first _n_ elements from the list.", default_value = nil },
          { name = "last", type = "Int", description = "Returns the last _n_ elements from the list.", default_value = nil },
          { name = "orderBy", type = "SponsorshipNewsletterOrder", description = "Ordering options for sponsorship updates returned from the connection.", default_value = "{field: CREATED_AT, direction: DESC}" },
        } },
        { name = "sponsorshipsAsMaintainer", type = "SponsorshipConnection!", description = "The sponsorships where this user or organization is the maintainer receiving the funds.", args = {
          { name = "activeOnly", type = "Boolean", description = "Whether to include only sponsorships that are active right now, versus all\nsponsorships this maintainer has ever received.", default_value = "true" },
          { name = "after", type = "String", description = "Returns the elements in the list that come after the specified cursor.", default_value = nil },
          { name = "before", type = "String", description = "Returns the elements in the list that come before the specified cursor.", default_value = nil },
          { name = "first", type = "Int", description = "Returns the first _n_ elements from the list.", default_value = nil },
          { name = "includePrivate", type = "Boolean", description = "Whether or not to include private sponsorships in the result set", default_value = "false" },
          { name = "last", type = "Int", description = "Returns the last _n_ elements from the list.", default_value = nil },
          { name = "orderBy", type = "SponsorshipOrder", description = "Ordering options for sponsorships returned from this connection. If left\nblank, the sponsorships will be ordered based on relevancy to the viewer.", default_value = nil },
        } },
        { name = "sponsorshipsAsSponsor", type = "SponsorshipConnection!", description = "The sponsorships where this user or organization is the funder.", args = {
          { name = "activeOnly", type = "Boolean", description = "Whether to include only sponsorships that are active right now, versus all sponsorships this sponsor has ever made.", default_value = "true" },
          { name = "after", type = "String", description = "Returns the elements in the list that come after the specified cursor.", default_value = nil },
          { name = "before", type = "String", description = "Returns the elements in the list that come before the specified cursor.", default_value = nil },
          { name = "first", type = "Int", description = "Returns the first _n_ elements from the list.", default_value = nil },
          { name = "last", type = "Int", description = "Returns the last _n_ elements from the list.", default_value = nil },
