          { name = "orderBy", type = "SponsorshipOrder", description = "Ordering options for sponsorships returned from this connection. If left\nblank, the sponsorships will be ordered based on relevancy to the viewer.", default_value = nil },
        } },
        { name = "totalSponsorshipAmountAsSponsorInCents", type = "Int", description = "The amount in United States cents (e.g., 500 = $5.00 USD) that this entity has\nspent on GitHub to fund sponsorships. Only returns a value when viewed by the\nuser themselves or by a user who can manage sponsorships for the requested organization.", args = {
