    ["SponsorsListing"] = {
      kind        = "OBJECT",
      name        = "SponsorsListing",
      description = "A GitHub Sponsors listing.",
      interfaces  = { "Node" },
      fields      = {
        { name = "activeGoal", type = "SponsorsGoal", description = "The current goal the maintainer is trying to reach with GitHub Sponsors, if any.", args = {} },
        { name = "activeStripeConnectAccount", type = "StripeConnectAccount", description = "The Stripe Connect account currently in use for payouts for this Sponsors\nlisting, if any. Will only return a value when queried by the maintainer\nthemselves, or by an admin of the sponsorable organization.", args = {} },
        { name = "billingCountryOrRegion", type = "String", description = "The name of the country or region with the maintainer's bank account or fiscal\nhost. Will only return a value when queried by the maintainer themselves, or\nby an admin of the sponsorable organization.", args = {} },
        { name = "contactEmailAddress", type = "String", description = "The email address used by GitHub to contact the sponsorable about their GitHub\nSponsors profile. Will only return a value when queried by the maintainer\nthemselves, or by an admin of the sponsorable organization.", args = {} },
        { name = "createdAt", type = "DateTime!", description = "Identifies the date and time when the object was created.", args = {} },
        { name = "dashboardResourcePath", type = "URI!", description = "The HTTP path for the Sponsors dashboard for this Sponsors listing.", args = {} },
        { name = "dashboardUrl", type = "URI!", description = "The HTTP URL for the Sponsors dashboard for this Sponsors listing.", args = {} },
        { name = "featuredItems", type = "[SponsorsListingFeaturedItem!]!", description = "The records featured on the GitHub Sponsors profile.", args = {
          { name = "featureableTypes", type = "[SponsorsListingFeaturedItemFeatureableType!]", description = "The types of featured items to return.", default_value = "[REPOSITORY, USER]" },
        } },
        { name = "fiscalHost", type = "Organization", description = "The fiscal host used for payments, if any. Will only return a value when\nqueried by the maintainer themselves, or by an admin of the sponsorable organization.", args = {} },
        { name = "fullDescription", type = "String!", description = "The full description of the listing.", args = {} },
        { name = "fullDescriptionHTML", type = "HTML!", description = "The full description of the listing rendered to HTML.", args = {} },
        { name = "id", type = "ID!", description = "The Node ID of the SponsorsListing object", args = {} },
        { name = "isPublic", type = "Boolean!", description = "Whether this listing is publicly visible.", args = {} },
        { name = "name", type = "String!", description = "The listing's full name.", args = {} },
        { name = "nextPayoutDate", type = "Date", description = "A future date on which this listing is eligible to receive a payout.", args = {} },
        { name = "residenceCountryOrRegion", type = "String", description = "The name of the country or region where the maintainer resides. Will only\nreturn a value when queried by the maintainer themselves, or by an admin of\nthe sponsorable organization.", args = {} },
        { name = "resourcePath", type = "URI!", description = "The HTTP path for this Sponsors listing.", args = {} },
        { name = "shortDescription", type = "String!", description = "The short description of the listing.", args = {} },
        { name = "slug", type = "String!", description = "The short name of the listing.", args = {} },
        { name = "sponsorable", type = "Sponsorable!", description = "The entity this listing represents who can be sponsored on GitHub Sponsors.", args = {} },
        { name = "tiers", type = "SponsorsTierConnection", description = "The tiers for this GitHub Sponsors profile.", args = {
          { name = "after", type = "String", description = "Returns the elements in the list that come after the specified cursor.", default_value = nil },
          { name = "before", type = "String", description = "Returns the elements in the list that come before the specified cursor.", default_value = nil },
          { name = "first", type = "Int", description = "Returns the first _n_ elements from the list.", default_value = nil },
          { name = "includeUnpublished", type = "Boolean", description = "Whether to include tiers that aren't published. Only admins of the Sponsors\nlisting can see draft tiers. Only admins of the Sponsors listing and viewers\nwho are currently sponsoring on a retired tier can see those retired tiers.\nDefaults to including only published tiers, which are visible to anyone who\ncan see the GitHub Sponsors profile.", default_value = "false" },
          { name = "last", type = "Int", description = "Returns the last _n_ elements from the list.", default_value = nil },
          { name = "orderBy", type = "SponsorsTierOrder", description = "Ordering options for Sponsors tiers returned from the connection.", default_value = "{field: MONTHLY_PRICE_IN_CENTS, direction: ASC}" },
        } },
        { name = "url", type = "URI!", description = "The HTTP URL for this Sponsors listing.", args = {} },
