      description = "SponsorsTier information only visible to users that can administer the associated Sponsors listing.",
      interfaces  = {},
      fields      = {
        { name = "isDraft", type = "Boolean!", description = "Indicates whether this tier is still a work in progress by the sponsorable and\nnot yet published to the associated GitHub Sponsors profile. Draft tiers\ncannot be used for new sponsorships and will not be in use on existing\nsponsorships. Draft tiers cannot be seen by anyone but the admins of the\nGitHub Sponsors profile.", args = {} },
